<script setup lang="ts">
import {computed,onMounted,onUnmounted,ref} from 'vue';
import {getServiceBase} from '@/services/api';
import {managementApi,type ManagementKind,type ManagementRow,type ManagementMeta,type ManagementConnection,type ModerationPolicy} from '@/services/management';
const props=defineProps<{kind:ManagementKind}>();
const labels:Record<ManagementKind,string>={videos:'视频管理',users:'用户管理',danmu:'弹幕管理',comments:'评论管理',requests:'求片管理',feedback:'意见反馈',reminders:'催更管理'};
const cmsKind=computed(()=>props.kind==='videos'||props.kind==='users');
const moderated=computed(()=>props.kind==='comments'||props.kind==='danmu');
const replyKind=computed(()=>props.kind==='requests'||props.kind==='feedback');
const title=computed(()=>labels[props.kind]);
const rows=ref<ManagementRow[]>([]),selected=ref<number[]>([]),total=ref(0),page=ref(1),pages=ref(1),pageSize=ref(10),jump=ref('1');
const loading=ref(false),mutating=ref(false),busy=computed(()=>loading.value||mutating.value);
const error=ref(''),notice=ref(''),loaded=ref(false),source=ref(''),blocked=ref(false);
const connection=ref<ManagementConnection|null>(null),meta=ref<ManagementMeta|null>(null),policy=ref<ModerationPolicy|null>(null);
const connectionOpen=ref(false),key=ref(''),reviewSwitchKey=ref(0);
const defaults=()=>({keyword:'',id:'',userId:'',videoId:'',episode:'',status:'',categoryId:'',groupId:'',level:'',reported:''});
const filters=ref(defaults());
const sort=ref('id'),order=ref('desc');
let alive=true,loadSequence=0;
const canWrite=computed(()=>loaded.value&&!!source.value&&!blocked.value&&(!cmsKind.value||meta.value?.source===source.value));
const allSelected=computed(()=>rows.value.length>0&&rows.value.every(row=>selected.value.includes(row.id)));
const categories=computed(()=>[{id:'',name:'全部分类'},...(meta.value?.categories||[]).map(c=>({id:String(c.id),name:(c.parentId?'　':'')+c.name}))]);
const groups=computed(()=>[{id:'',name:'全部用户组'},...(meta.value?.groups||[]).map(g=>({id:String(g.id),name:g.name}))]);
const statuses=computed(()=>[{id:'',name:moderated.value?'审核状态':'全部状态'},{id:'1',name:moderated.value?'已审核':'启用'},{id:'0',name:moderated.value?'未审核':'禁用'}]);
const levels=[{id:'',name:'全部推荐'},...Array.from({length:10},(_,i)=>({id:String(i),name:i?'推荐 '+i:'未推荐'}))];
const reports=[{id:'',name:'举报状态'},{id:'1',name:'已被举报'}];
const sizes=[10,20,50,100];
const choiceName=(list:{id:string;name:string}[],value:string)=>list.find(item=>item.id===value)?.name||list[0]?.name||'请选择';
const choiceIndex=(list:{id:string;name:string}[],value:string)=>Math.max(0,list.findIndex(item=>item.id===value));
const categoryIndex=(value:string)=>Math.max(0,(meta.value?.categories||[]).findIndex(item=>String(item.id)===value));
const valueAt=(list:{id:string;name:string}[],event:any)=>list[Number(event.detail.value)]?.id||'';
function describe(e:unknown){return e instanceof Error?e.message:'操作失败，请重试';}
function stamp(value?:number|string){if(!value)return '—';const date=new Date(typeof value==='number'?value*1000:value);return Number.isNaN(date.getTime())?'—':date.toLocaleString('zh-CN',{hour12:false});}
function toggle(id:number){if(busy.value)return;selected.value=selected.value.includes(id)?selected.value.filter(i=>i!==id):[...selected.value,id];}
function toggleAll(){if(!busy.value)selected.value=allSelected.value?[]:rows.value.map(row=>row.id);}
async function refresh(){
 if(busy.value)return;
 const sequence=++loadSequence;loading.value=true;loaded.value=false;error.value='';selected.value=[];
 try{
  const conn=await managementApi.connection();if(!alive||sequence!==loadSequence)return;connection.value=conn;
  if(!conn.base)throw new Error('请先在「系统管理 → 内容源与连接」中连接苹果 CMS。');
  const results=await Promise.all([managementApi.list(props.kind,{...filters.value,page:page.value,pageSize:pageSize.value,sort:sort.value,order:order.value}),cmsKind.value?managementApi.meta():Promise.resolve(null),moderated.value?managementApi.policy():Promise.resolve(null)]);
  if(!alive||sequence!==loadSequence)return;
  const [list,nextMeta,nextPolicy]=results;
  if(!list.source||list.source!==conn.base||nextMeta&&nextMeta.source!==list.source||nextPolicy&&nextPolicy.source!==list.source)throw new Error('内容源已更改，请重新刷新列表。');
  rows.value=list.items;total.value=list.total;page.value=list.page;pages.value=Math.max(1,list.pages);jump.value=String(list.page);source.value=list.source;meta.value=nextMeta;policy.value=nextPolicy;loaded.value=true;blocked.value=false;
 }catch(e){if(alive&&sequence===loadSequence){error.value=describe(e);rows.value=[];total.value=0;source.value='';meta.value=null;policy.value=null;const code=(e as any)?.code;if(code==='CMS_MANAGEMENT_SETUP'||code==='CMS_MANAGEMENT_UNAVAILABLE')connectionOpen.value=true;}}
 finally{if(alive&&sequence===loadSequence)loading.value=false;}
}
function search(){if(busy.value)return;page.value=1;notice.value='';void refresh();}
function reset(){if(busy.value)return;filters.value=defaults();sort.value='id';order.value='desc';search();}
function changePage(next:number){if(busy.value||!Number.isInteger(next)||next<1||next>pages.value)return;page.value=next;void refresh();}
function changeSize(event:any){if(busy.value)return;pageSize.value=sizes[Number(event.detail.value)]||10;page.value=1;void refresh();}
function changeSort(field:string){if(busy.value)return;order.value=sort.value===field&&order.value==='desc'?'asc':'desc';sort.value=field;page.value=1;void refresh();}
async function confirmation(content:string){return new Promise<boolean>(resolve=>uni.showModal({title:'确认删除',content,confirmText:'删除',confirmColor:'#dc4554',success:r=>resolve(!!r.confirm),fail:()=>resolve(false)}));}
async function perform(action:string,targets:ManagementRow[],extra:Record<string,unknown>={},expectedSource=source.value){
 if(busy.value||!canWrite.value||expectedSource!==source.value)return false;
 mutating.value=true;error.value='';notice.value='';
 try{
  const result=await managementApi.action(props.kind,{source:expectedSource,action,ids:targets.map(row=>row.id),versions:Object.fromEntries(targets.map(row=>[String(row.id),row.version])),...extra});
  if(!alive)return false;
  if(result.source!==expectedSource)throw Object.assign(new Error('操作响应的内容源不一致，请先刷新核对结果。'),{code:'CMS_WRITE_UNCONFIRMED'});
  notice.value=(result.warnings?.length?result.warnings.join('；'):'操作成功，已更新 '+result.affected+' 条记录。');return true;
 }catch(e){if(alive){error.value=describe(e);if(['CMS_WRITE_UNCONFIRMED','MANAGEMENT_SOURCE_CHANGED','MANAGEMENT_RECORD_CHANGED'].includes((e as any)?.code)){blocked.value=true;editor.value=null;batch.value=null;policyEditor.value=null;policySnapshot.value=null;}}return false;}
 finally{if(alive)mutating.value=false;}
}
function targets(){return rows.value.filter(row=>selected.value.includes(row.id));}
async function remove(items:ManagementRow[]){if(!items.length||busy.value||!canWrite.value)return;const captured=source.value;if(!await confirmation('将删除所选 '+items.length+' 条记录，删除后无法恢复。'))return;if(await perform('delete',items,{},captured))await refresh();}
async function moderate(action:'approve'|'unapprove'){const items=targets();if(items.length&&await perform(action,items))await refresh();}
const batch=ref<{action:string;source:string;rows:ManagementRow[]}|null>(null),batchValue=ref('');
function openBatch(action:string){if(!canWrite.value||busy.value||!selected.value.length)return;error.value='';batch.value={action,source:source.value,rows:targets().map(row=>({...row}))};batchValue.value=action==='status'?'1':action==='level'?'0':String(meta.value?.categories[0]?.id||'');}
async function submitBatch(){const current=batch.value;if(!current)return;const n=Number(batchValue.value);if(!Number.isInteger(n)||batchValue.value===''){error.value='请选择有效的批量设置。';return;}if(await perform(current.action,current.rows,{value:n},current.source)){batch.value=null;await refresh();}}
const editor=ref<{mode:'create'|'edit'|'reply';source:string;row:ManagementRow|null}|null>(null);
const form=ref<Record<string,string>>({});
const userGroups=ref<string[]>([]);
function dateInput(seconds?:number){if(!seconds)return '';const d=new Date(seconds*1000);const pad=(n:number)=>String(n).padStart(2,'0');return d.getFullYear()+'-'+pad(d.getMonth()+1)+'-'+pad(d.getDate())+' '+pad(d.getHours())+':'+pad(d.getMinutes());}
function openEditor(row:ManagementRow|null,mode:'create'|'edit'|'reply'='edit'){
 if(busy.value||!canWrite.value)return;
 error.value='';const item=row?{...row}:null;editor.value={mode,source:source.value,row:item};
 form.value={name:row?.name||'',nickname:row?.nickname||'',categoryId:String(row?.categoryId||meta.value?.categories[0]?.id||''),status:String(row?.status??1),level:String(row?.level??0),year:row?.year||'',area:row?.area||'',points:String(row?.points??0),expiresAt:dateInput(row?.expiresAt),password:'',content:row?.content||'',reply:row?.reply||''};
 userGroups.value=String(row?.groupId||meta.value?.groups.find(group=>group.id===2)?.id||'').split(',').filter(Boolean);
}
function toggleGroup(id:number){if(busy.value)return;const value=String(id);userGroups.value=userGroups.value.includes(value)?userGroups.value.filter(item=>item!==value):[...userGroups.value,value];}
async function submitEditor(){
 const current=editor.value;if(!current||busy.value)return;
 try{
  let fields:Record<string,unknown>={};const draft=form.value;
  if(current.mode==='reply')fields={reply:draft.reply};
  else if(props.kind==='videos'){
   if(!draft.name.trim())throw new Error('请输入视频名称。');
   if(!meta.value?.categories.some(item=>String(item.id)===draft.categoryId))throw new Error('请选择视频分类。');
   fields={name:draft.name.trim(),categoryId:Number(draft.categoryId),status:Number(draft.status),level:Number(draft.level),year:draft.year.trim(),area:draft.area.trim()};
  }else if(props.kind==='users'){
   if(!draft.name.trim())throw new Error('请输入用户名。');if(current.mode==='create'&&!draft.password)throw new Error('新建用户必须设置密码。');
   if(!userGroups.value.length)throw new Error('至少选择一个用户组。');
   if(!/^\d+$/.test(draft.points)||Number(draft.points)>2147483647)throw new Error('积分应为 0–2147483647 的整数。');
   let expiry=0;if(draft.expiresAt.trim()){if(!/^\d{4}-\d{2}-\d{2} \d{2}:\d{2}$/.test(draft.expiresAt.trim()))throw new Error('有效期格式应为 YYYY-MM-DD HH:mm，留空为普通会员。');expiry=Math.floor(new Date(draft.expiresAt.trim().replace(' ','T')).getTime()/1000);if(!Number.isInteger(expiry)||expiry<1||expiry>2147483647||dateInput(expiry)!==draft.expiresAt.trim())throw new Error('会员有效期无效。');}
   fields={name:draft.name.trim(),nickname:draft.nickname.trim(),groupId:userGroups.value.join(','),status:Number(draft.status),points:Number(draft.points),expiresAt:expiry,...(draft.password?{password:draft.password}:{})};
  }else fields={content:draft.content};
  const action=current.mode==='create'?'create':current.mode==='reply'?'reply':'edit';
  const extra=cmsKind.value?{fields}:fields;
  if(await perform(action,current.row?[current.row]:[],extra,current.source)){editor.value=null;form.value={};await refresh();}
 }catch(e){error.value=describe(e);}
}
const policyEditor=ref<'keywords'|'ips'|null>(null),policyText=ref(''),policySnapshot=ref<ModerationPolicy|null>(null);
function openPolicy(mode:'keywords'|'ips'){if(!policy.value||busy.value||!canWrite.value)return;error.value='';policySnapshot.value={...policy.value,keywords:[...policy.value.keywords],ips:[...policy.value.ips]};policyText.value=policy.value[mode].join('\n');policyEditor.value=mode;}
async function savePolicy(next:ModerationPolicy){
 if(busy.value||!canWrite.value||next.source!==source.value)return false;mutating.value=true;error.value='';
 try{const result=await managementApi.savePolicy(next);if(alive){if(result.source!==next.source)throw Object.assign(new Error('内容源已更改，请刷新。'),{code:'MANAGEMENT_SOURCE_CHANGED'});policy.value=result;notice.value='审核规则已保存。';}return true;}
 catch(e){if(alive){error.value=describe(e);if(['MANAGEMENT_SOURCE_CHANGED','MANAGEMENT_RECORD_CHANGED'].includes((e as any)?.code)){blocked.value=true;policyEditor.value=null;policySnapshot.value=null;}}return false;}
 finally{if(alive)mutating.value=false;}
}
async function submitPolicy(){if(!policySnapshot.value||!policyEditor.value)return;const next={...policySnapshot.value,[policyEditor.value]:policyText.value.split(/\r?\n/).map(line=>line.trim()).filter(Boolean)};if(await savePolicy(next)){policyEditor.value=null;policySnapshot.value=null;}}
async function toggleReview(event:any){if(!policy.value)return;const next={...policy.value,[props.kind==='comments'?'reviewComments':'reviewDanmu']:!!event.detail.value};try{await savePolicy(next);}finally{if(alive)reviewSwitchKey.value++;}}
async function configure(mode:'key'|'install'|'test'){
 if(busy.value||!connection.value?.base)return;mutating.value=true;error.value='';notice.value='';
 try{
  const expected=connection.value.base;
  if(mode==='key'){if(!/^[a-fA-F0-9]{64}$/.test(key.value.trim()))throw new Error('请输入 64 位十六进制管理密钥。');await managementApi.connect(expected,key.value.trim());key.value='';}
  else if(mode==='install')await managementApi.install(expected);
  else{const result=await managementApi.test();if(result.source!==expected)throw new Error('内容源已更改，请刷新。');}
  if(alive)notice.value=mode==='test'?'管理适配器连接正常。':'管理适配器已配置。';
 }catch(e){if(alive)error.value=describe(e);return;}
 finally{if(alive)mutating.value=false;}
 if(alive)await refresh();
}
function downloadAdapter(){
 // #ifdef H5
 window.open(getServiceBase()+'/api/admin/manage/adapter','_blank','noopener');
 // #endif
}
const tableStyle=computed(()=>({gridTemplateColumns:props.kind==='videos'?'44px 76px minmax(240px,2fr) 86px 82px 130px 80px 100px 100px':props.kind==='users'?'44px 76px minmax(170px,1fr) 130px 88px 90px 166px 160px 130px':moderated.value?'44px 70px 150px 96px minmax(260px,2fr) 170px 144px':replyKind.value?'44px 70px 155px minmax(240px,1fr) minmax(200px,1fr) 166px 130px':'44px 70px 155px minmax(250px,1fr) 166px 90px 100px'}));
onMounted(()=>void refresh());
onUnmounted(()=>{alive=false;loadSequence++;key.value='';form.value={};});
</script>
<template>
 <view class="management-page">
  <view class="page-heading"><view><text class="eyebrow">CONTENT & COMMUNITY</text><text class="page-title">{{title}}</text><text class="subtitle">{{cmsKind?'管理苹果 CMS 中的'+(kind==='videos'?'影视内容':'会员账户'):'管理 App 提交的'+title.replace('管理','')+'记录'}}</text></view><text class="scope-tag">四端共享</text></view>
  <view v-if="error" class="alert error" role="alert"><text>{{error}}</text><button v-if="blocked" :disabled="busy" @click="refresh">刷新核对</button></view>
  <view v-if="notice" class="alert success" role="status">{{notice}}</view>
  <view v-if="cmsKind" class="connection-panel">
   <button class="connection-toggle" :aria-expanded="connectionOpen" @click="connectionOpen=!connectionOpen"><text class="connection-dot" :class="{ready:loaded}"/><text>{{loaded?'苹果 CMS 管理已连接':connection?.configured?'管理适配器已配置':'苹果 CMS 管理连接'}}</text><text class="connection-source">{{connection?.base||'尚未设置内容源'}}</text><text>{{connectionOpen?'收起':'配置连接'}} {{connectionOpen?'⌃':'⌄'}}</text></button>
   <view v-if="connectionOpen" class="connection-body"><text>将管理适配器安装到苹果 CMS，再填写与密钥文件一致的管理密钥。</text><text class="path-hint">控制器：application/index/controller/Hetunops.php · 密钥：application/extra/hetun_operations.php</text><view class="connection-controls"><button class="btn" @click="downloadAdapter">下载适配器</button><button v-if="connection?.localAvailable" class="btn" :disabled="busy" @click="configure('install')">安装到本地 CMS</button><input v-model="key" class="key-input" password placeholder="64 位管理密钥" maxlength="64" :disabled="busy" autocomplete="off"/><button class="btn blue" :disabled="busy||!key.trim()||!connection?.base" @click="configure('key')">保存密钥</button><button class="btn" :disabled="busy||!connection?.configured" @click="configure('test')">测试连接</button></view></view>
  </view>
  <view class="filter-card">
   <view class="filter-line">
    <template v-if="kind==='videos'"><picker :range="categories" :value="choiceIndex(categories,filters.categoryId)" range-key="name" :disabled="busy" @change="filters.categoryId=valueAt(categories,$event)"><view class="select">{{choiceName(categories,filters.categoryId)}}<text>⌄</text></view></picker></template>
    <template v-if="kind==='users'"><input v-model="filters.id" class="filter-input narrow" placeholder="用户 ID" type="number" :disabled="busy" @confirm="search"/><picker :range="groups" :value="choiceIndex(groups,filters.groupId)" range-key="name" :disabled="busy" @change="filters.groupId=valueAt(groups,$event)"><view class="select">{{choiceName(groups,filters.groupId)}}<text>⌄</text></view></picker></template>
    <picker v-if="cmsKind||moderated" :range="statuses" :value="choiceIndex(statuses,filters.status)" range-key="name" :disabled="busy" @change="filters.status=valueAt(statuses,$event)"><view class="select">{{choiceName(statuses,filters.status)}}<text>⌄</text></view></picker>
    <picker v-if="kind==='videos'" :range="levels" :value="choiceIndex(levels,filters.level)" range-key="name" :disabled="busy" @change="filters.level=valueAt(levels,$event)"><view class="select">{{choiceName(levels,filters.level)}}<text>⌄</text></view></picker>
    <template v-if="!cmsKind"><input v-model="filters.userId" class="filter-input narrow" placeholder="用户 ID" type="number" :disabled="busy" @confirm="search"/><input v-if="kind==='reminders'||moderated" v-model="filters.videoId" class="filter-input narrow" placeholder="视频 ID" type="number" :disabled="busy" @confirm="search"/></template>
    <input v-if="kind==='danmu'" v-model="filters.episode" class="filter-input narrow" placeholder="集数" type="number" :disabled="busy" @confirm="search"/>
     <picker v-if="moderated" :range="reports" :value="choiceIndex(reports,filters.reported)" range-key="name" :disabled="busy" @change="filters.reported=valueAt(reports,$event)"><view class="select">{{choiceName(reports,filters.reported)}}<text>⌄</text></view></picker>
    <input v-model="filters.keyword" class="filter-input keyword" :placeholder="kind==='videos'?'视频名称':kind==='users'?'用户名或昵称':kind==='reminders'?'昵称或视频名称':'昵称或内容'" :disabled="busy" @confirm="search"/>
    <button class="btn blue" :disabled="busy" @click="search"><text>⌕</text> 搜索</button><button class="btn" :disabled="busy" @click="reset">↺ 重置</button><button class="btn" :disabled="busy" @click="refresh">↻ {{loading?'加载中…':'刷新'}}</button>
    <button v-if="kind==='users'" class="btn blue add-user" :disabled="busy||!canWrite" @click="openEditor(null,'create')">＋ 添加用户</button>
   </view>
   <view class="action-line"><text class="selection-count">已选 {{selected.length}} 项</text>
    <template v-if="cmsKind"><button class="btn compact" :disabled="busy||!canWrite||!selected.length" @click="openBatch('status')">批量状态 ⌄</button><button v-if="kind==='videos'" class="btn compact" :disabled="busy||!canWrite||!selected.length" @click="openBatch('category')">批量分类 ⌄</button><button v-if="kind==='videos'" class="btn compact" :disabled="busy||!canWrite||!selected.length" @click="openBatch('level')">批量推荐 ⌄</button></template>
    <template v-if="moderated"><button class="btn green" :disabled="busy||!canWrite||!selected.length" @click="moderate('approve')">✓ 批量审核</button><button class="btn amber" :disabled="busy||!canWrite||!selected.length" @click="moderate('unapprove')">↶ 设为未审</button></template>
    <button v-if="kind!=='videos'" class="btn red" :disabled="busy||!canWrite||!selected.length" @click="remove(targets())">批量删除</button>
    <template v-if="moderated"><view class="action-spacer"/><view class="review-toggle"><text>新{{kind==='comments'?'评论':'弹幕'}}需审核</text><switch :key="reviewSwitchKey" :checked="kind==='comments'?policy?.reviewComments??true:policy?.reviewDanmu??true" :disabled="busy||!canWrite||!policy" color="#2864e9" @change="toggleReview"/></view><button class="btn compact" :disabled="busy||!policy||!canWrite" @click="openPolicy('keywords')">关键词黑名单</button><button class="btn compact" :disabled="busy||!policy||!canWrite" @click="openPolicy('ips')">IP 黑名单</button></template>
   </view>
  </view>
  <view class="table-card" :aria-busy="loading"><scroll-view scroll-x class="table-scroll"><view class="data-table" role="table" :aria-label="title">
   <view class="table-row table-head" :style="tableStyle" role="row"><view class="check-cell"><button class="checkbox" role="checkbox" :aria-checked="allSelected" aria-label="全选当前页" :disabled="busy||!loaded||!rows.length" :class="{checked:allSelected}" @click="toggleAll">{{allSelected?'✓':''}}</button></view><view class="cell"><button class="sort-button" :disabled="busy" @click="changeSort('id')">ID <text>{{sort==='id'?(order==='desc'?'↓':'↑'):'↕'}}</text></button></view>
    <template v-if="kind==='videos'"><view class="cell">视频信息</view><view class="cell">状态</view><view class="cell"><button class="sort-button" :disabled="busy" @click="changeSort('level')">推荐 ↕</button></view><view class="cell">播放源</view><view class="cell">年份</view><view class="cell">地区</view></template>
    <template v-else-if="kind==='users'"><view class="cell">用户信息</view><view class="cell">用户组</view><view class="cell">状态</view><view class="cell">积分</view><view class="cell">会员有效期</view><view class="cell">最近登录</view></template>
    <template v-else-if="moderated"><view class="cell">用户 / 视频</view><view class="cell">审核状态</view><view class="cell">{{kind==='danmu'?'弹幕':'评论'}}内容</view><view class="cell">提交时间</view></template>
    <template v-else-if="replyKind"><view class="cell">用户信息</view><view class="cell">{{kind==='requests'?'求片内容':'反馈内容'}}</view><view class="cell">回复内容</view><view class="cell">提交时间</view></template>
    <template v-else><view class="cell">用户信息</view><view class="cell">视频信息</view><view class="cell">催更时间</view><view class="cell"><button class="sort-button" :disabled="busy" @click="changeSort('count')">次数 ↕</button></view></template><view class="cell">操作</view>
   </view>
   <view v-for="row in rows" :key="row.id" class="table-row" :class="{selected:selected.includes(row.id)}" :style="tableStyle" role="row"><view class="check-cell"><button class="checkbox" role="checkbox" :aria-checked="selected.includes(row.id)" :aria-label="'选择记录 '+row.id" :disabled="busy" :class="{checked:selected.includes(row.id)}" @click="toggle(row.id)">{{selected.includes(row.id)?'✓':''}}</button></view><view class="cell muted numeric">{{row.id}}</view>
    <template v-if="kind==='videos'"><view class="cell video-cell"><image v-if="row.cover" class="poster" :src="row.cover" mode="aspectFill"/><view><text class="record-name">{{row.name}}</text><text class="record-detail">{{row.categoryName||'未分类'}}</text></view></view><view class="cell"><text class="status-chip" :class="{enabled:row.status===1}">{{row.status===1?'启用':'禁用'}}</text></view><view class="cell">{{row.level?'推荐 '+row.level:'—'}}</view><view class="cell wrap">{{row.sources||'—'}}</view><view class="cell">{{row.year||'—'}}</view><view class="cell">{{row.area||'—'}}</view></template>
    <template v-else-if="kind==='users'"><view class="cell"><view><text class="record-name">{{row.name}}</text><text class="record-detail">{{row.nickname||'未设置昵称'}}</text></view></view><view class="cell wrap">{{row.groupName||'—'}}</view><view class="cell"><text class="status-chip" :class="{enabled:row.status===1}">{{row.status===1?'启用':'禁用'}}</text></view><view class="cell numeric">{{row.points??0}}</view><view class="cell muted">{{row.expiresAt?stamp(row.expiresAt):'普通会员'}}</view><view class="cell"><view><text class="record-detail">{{stamp(row.lastLoginAt)}}</text><text class="record-detail">{{row.lastLoginIP||'—'}}</text></view></view></template>
    <template v-else-if="moderated"><view class="cell"><view><text class="record-name">{{row.nickname||'用户 '+row.userId}}</text><text class="record-detail">用户 {{row.userId}} · 视频 {{row.videoId}}</text><text class="record-detail wrap">{{row.videoName}}</text></view></view><view class="cell"><view><text class="status-chip" :class="{enabled:row.approved}">{{row.approved?'已审核':'未审核'}}</text><text v-if="row.reports" class="reported">举报 {{row.reports}}</text></view></view><view class="cell wrap content-cell"><view><text>{{row.content}}</text><text v-if="kind==='danmu'" class="record-detail">播放位置 {{Math.floor((row.position||0)/1000)}} 秒</text></view></view><view class="cell muted">{{stamp(row.createdAt)}}</view></template>
    <template v-else-if="replyKind"><view class="cell"><view><text class="record-name">{{row.nickname||'用户 '+row.userId}}</text><text class="record-detail">ID {{row.userId}} · {{row.ip||'—'}}</text></view></view><view class="cell wrap content-cell">{{row.content}}</view><view class="cell wrap"><text :class="{muted:!row.reply}">{{row.reply||'待回复'}}</text></view><view class="cell muted">{{stamp(row.createdAt)}}</view></template>
    <template v-else><view class="cell"><view><text class="record-name">{{row.nickname||'用户 '+row.userId}}</text><text class="record-detail">用户 ID {{row.userId}}</text></view></view><view class="cell"><view><text class="record-name wrap">{{row.videoName}}</text><text class="record-detail">视频 ID {{row.videoId}}</text></view></view><view class="cell muted">{{stamp(row.updatedAt||row.createdAt)}}</view><view class="cell numeric">{{row.count||1}}</view></template>
    <view class="cell row-actions"><button v-if="kind!=='reminders'" class="text-button" :disabled="busy||!canWrite" @click="openEditor(row,replyKind?'reply':'edit')">{{replyKind?'回复':'编辑'}}</button><button v-if="kind!=='videos'" class="text-button danger" :disabled="busy||!canWrite" @click="remove([row])">删除</button></view>
   </view>
   <view v-if="!rows.length" class="empty-state" role="status"><text class="empty-symbol">{{loading?'↻':error?'!':'▤'}}</text><text>{{loading?'正在加载…':error?'暂时无法读取数据':'暂无数据'}}</text><text class="empty-hint">{{loading?'请稍候':error?'请处理上方提示后刷新':cmsKind?'调整筛选条件，或在苹果 CMS 中添加内容':'App 提交的记录会显示在这里'}}</text></view>
  </view></scroll-view></view>
  <view class="pagination"><text>共 {{total}} 条</text><picker :range="sizes.map(n=>n+' 条 / 页')" :value="sizes.indexOf(pageSize)" :disabled="busy" @change="changeSize"><view class="select page-size">{{pageSize}} 条 / 页 <text>⌄</text></view></picker><view class="page-controls"><button :disabled="busy||!loaded||page<=1" aria-label="上一页" @click="changePage(page-1)">‹</button><text>{{page}} / {{pages}}</text><button :disabled="busy||!loaded||page>=pages" aria-label="下一页" @click="changePage(page+1)">›</button></view><text>前往</text><input v-model="jump" class="jump-input" type="number" :disabled="busy||!loaded" aria-label="跳转页码" @confirm="changePage(Number(jump))"/><button class="jump-button" :disabled="busy||!loaded" @click="changePage(Number(jump))">页 ↵</button></view>
  <text v-if="!cmsKind" class="storage-note">记录存储于运营服务，并按 CMS 内容源隔离；既有 CMS 历史记录不会自动导入。</text>
  <view v-if="editor||batch||policyEditor" class="modal-overlay" @click.self="!busy&&(editor=null,batch=null,policyEditor=null)"><view class="modal" role="dialog" aria-modal="true" :aria-label="editor?(editor.mode==='create'?'添加用户':editor.mode==='reply'?'回复':'编辑'):(batch?'批量设置':'黑名单设置')">
   <view class="modal-heading"><text>{{editor?(editor.mode==='create'?'添加用户':editor.mode==='reply'?'回复'+(kind==='requests'?'求片':'反馈'):'编辑'+title.replace('管理','')):batch?'批量'+({status:'状态',category:'分类',level:'推荐'}[batch.action]||'设置'):policyEditor==='keywords'?'关键词黑名单':'IP 黑名单'}}</text><button aria-label="关闭" :disabled="busy" @click="editor=null;batch=null;policyEditor=null">×</button></view>
   <scroll-view scroll-y class="modal-body"><view v-if="error" class="alert error" role="alert">{{error}}</view><template v-if="editor"><text v-if="editor.row" class="modal-record">记录 ID {{editor.row.id}}</text>
    <template v-if="editor.mode==='reply'"><view class="original-content">{{editor.row?.content}}</view><label class="field"><text>回复内容</text><textarea v-model="form.reply" :disabled="busy" maxlength="2000" placeholder="填写回复，用户可在自己的记录中查看"/></label></template>
    <template v-else-if="kind==='videos'"><label class="field"><text>视频名称</text><input v-model="form.name" :disabled="busy" maxlength="200" :focus="true"/></label><view class="form-grid"><view class="field"><text>分类</text><picker :range="meta?.categories||[]" :value="categoryIndex(form.categoryId)" range-key="name" :disabled="busy" @change="form.categoryId=String(meta?.categories[Number($event.detail.value)]?.id||'')"><view class="form-select">{{meta?.categories.find(c=>String(c.id)===form.categoryId)?.name||'请选择分类'}} ⌄</view></picker></view><view class="field"><text>状态</text><picker :range="['启用','禁用']" :value="form.status==='1'?0:1" :disabled="busy" @change="form.status=Number($event.detail.value)===0?'1':'0'"><view class="form-select">{{form.status==='1'?'启用':'禁用'}} ⌄</view></picker></view><label class="field"><text>年份</text><input v-model="form.year" :disabled="busy" maxlength="10"/></label><label class="field"><text>地区</text><input v-model="form.area" :disabled="busy" maxlength="20"/></label><view class="field"><text>推荐等级</text><picker :range="levels.slice(1)" range-key="name" :value="Number(form.level)" :disabled="busy" @change="form.level=String($event.detail.value)"><view class="form-select">{{form.level==='0'?'未推荐':'推荐 '+form.level}} ⌄</view></picker></view></view></template>
    <template v-else-if="kind==='users'"><view class="form-grid"><label class="field"><text>用户名 *</text><input v-model="form.name" :disabled="busy" maxlength="50" :focus="true"/></label><label class="field"><text>昵称</text><input v-model="form.nickname" :disabled="busy" maxlength="50"/></label></view><label class="field"><text>{{editor.mode==='create'?'密码 *':'新密码（留空保留原密码）'}}</text><input v-model="form.password" :disabled="busy" password maxlength="128" autocomplete="new-password"/></label><view class="field"><text>用户组 *</text><view class="group-choices"><button v-for="group in (meta?.groups||[]).filter(g=>g.id>=2)" :key="group.id" class="group-choice" :class="{chosen:userGroups.includes(String(group.id))}" :disabled="busy" :aria-pressed="userGroups.includes(String(group.id))" @click="toggleGroup(group.id)">{{userGroups.includes(String(group.id))?'✓ ':''}}{{group.name}}</button></view></view><view class="form-grid"><label class="field"><text>积分</text><input v-model="form.points" :disabled="busy" type="number"/></label><view class="field"><text>状态</text><picker :range="['启用','禁用']" :value="form.status==='1'?0:1" :disabled="busy" @change="form.status=Number($event.detail.value)===0?'1':'0'"><view class="form-select">{{form.status==='1'?'启用':'禁用'}} ⌄</view></picker></view></view><label class="field"><text>会员有效期</text><input v-model="form.expiresAt" :disabled="busy" placeholder="YYYY-MM-DD HH:mm，留空为普通会员" maxlength="16"/></label></template>
    <label v-else class="field"><text>内容</text><textarea v-model="form.content" :disabled="busy" :maxlength="kind==='danmu'?100:2000" :focus="true"/></label>
   </template><template v-else-if="batch"><text class="modal-record">已选 {{batch.rows.length}} 条记录</text><view class="field"><text>设置为</text><picker v-if="batch.action==='status'" :range="['启用','禁用']" :value="batchValue==='1'?0:1" :disabled="busy" @change="batchValue=Number($event.detail.value)===0?'1':'0'"><view class="form-select">{{batchValue==='1'?'启用':'禁用'}} ⌄</view></picker><picker v-else-if="batch.action==='category'" :range="meta?.categories||[]" :value="categoryIndex(batchValue)" range-key="name" :disabled="busy" @change="batchValue=String(meta?.categories[Number($event.detail.value)]?.id||'')"><view class="form-select">{{meta?.categories.find(c=>String(c.id)===batchValue)?.name||'请选择分类'}} ⌄</view></picker><picker v-else :range="levels.slice(1)" range-key="name" :value="Number(batchValue)" :disabled="busy" @change="batchValue=String($event.detail.value)"><view class="form-select">{{batchValue==='0'?'未推荐':'推荐 '+batchValue}} ⌄</view></picker></view></template><template v-else><text class="modal-record">每行填写一项，最多 200 项。规则应用于后续提交的全部评论、弹幕、求片和反馈。</text><textarea v-model="policyText" class="policy-textarea" :disabled="busy" maxlength="20400" :placeholder="policyEditor==='ips'?'例如：192.0.2.1':'每行一个关键词'"/></template></scroll-view>
   <view class="modal-footer"><text v-if="blocked" class="danger">请先刷新核对结果</text><button class="btn" :disabled="busy" @click="editor=null;batch=null;policyEditor=null">取消</button><button class="btn blue" :disabled="busy||!canWrite" @click="editor?submitEditor():batch?submitBatch():submitPolicy()">{{mutating?'正在保存…':'保存'}}</button></view>
  </view></view>
 </view>
</template>
